import{_ as t,o as r,c as i,a0 as a}from"./chunks/framework.CShDTZbC.js";const g=JSON.parse('{"title":"DevFix Improvement Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),o={name:"changelog.md"};function n(d,e,s,l,c,h){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="devfix-improvement-changelog" tabindex="-1">DevFix Improvement Changelog <a class="header-anchor" href="#devfix-improvement-changelog" aria-label="Permalink to &quot;DevFix Improvement Changelog&quot;">​</a></h1><h2 id="executive-summary" tabindex="-1">Executive Summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive Summary&quot;">​</a></h2><p>DevFix began as a highly experimental LLM troubleshooting script operating directly on the host machine with a crude, self-terminating loop. Over several distinct engineering phases, we learned that providing stronger prompts or switching models is insufficient to guarantee reliable troubleshooting. The LLM must be stripped of its ability to hallucinate success.</p><p>Through rigorous experimentation, we transformed DevFix into a completely deterministic, sandbox-isolated autonomous recovery system. The most material improvement to the system came not from a prompt change, but from the implementation of the <strong>Deterministic Verifier</strong>, which forced the agent to achieve an objectively measured success state before completing its task.</p><h2 id="improvement-timeline" tabindex="-1">Improvement Timeline <a class="header-anchor" href="#improvement-timeline" aria-label="Permalink to &quot;Improvement Timeline&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>Experiment / Change</th><th>Before</th><th>After</th><th>Result</th><th>Evidence</th></tr></thead><tbody><tr><td><strong>3F</strong></td><td>Gemini Free Tier experiment</td><td>Sandbox baseline</td><td>Quota-limited</td><td>Inconclusive</td><td><code>docs/</code> artifacts; frequent API quota limitations prevented reliable evaluation of model capability.</td></tr><tr><td><strong>3G</strong></td><td>OpenAI gpt-4o-mini</td><td>No baseline</td><td>1/5 Verified</td><td>20% Recovery</td><td>Demonstrated tool-calling reliability but highlighted reasoning bottlenecks in multi-step environment failures.</td></tr><tr><td><strong>3H</strong></td><td>Prompt/Controller Discipline</td><td>1/5 Verified</td><td>1/5 Verified</td><td>No improvement</td><td>Strict OBSERVE → HYPOTHESIZE → VERIFY loop added, but duplicate detection suppressed legitimate inspections.</td></tr><tr><td><strong>3I</strong></td><td>DeepSeek Model Swap</td><td>1/5 Verified</td><td>1/5 Verified</td><td>Iteration blocked</td><td>Swapped to DeepSeek; hit hard DEV-05 iteration budget limits (8 iterations) and DEV-03 verifier constraints.</td></tr><tr><td><strong>3J</strong></td><td>Benchmark Calibration</td><td>1/5 Verified</td><td>3/5 Verified</td><td>60% Recovery</td><td>MAX_ITERATIONS increased (8 → 15) and DEV-03 verifier corrected. Proved evaluation design materially affects measured performance.</td></tr><tr><td><strong>4B</strong></td><td>Async Sandbox &amp; Security</td><td><code>execSync</code> execution</td><td>Async execution</td><td>Hardened</td><td>Enforced timeouts, path traversal protection, and permission preservation inside Docker.</td></tr><tr><td><strong>4C</strong></td><td>Deterministic Verifier</td><td>Heuristic checks</td><td>Generic Process/HTTP</td><td>Hardened</td><td>Host-shell interpolation vulnerability discovered and fixed. LLM fully decoupled from success evaluation.</td></tr><tr><td><strong>4D</strong></td><td>Production Agent Controller</td><td>Experimental scripts</td><td>Provider Abstraction</td><td>Stabilized</td><td>Clean provider abstraction, dynamic verification, and structured telemetry established.</td></tr><tr><td><strong>4E</strong></td><td>Production CLI</td><td>Bare Node scripts</td><td>Interactive CLI</td><td>Polished</td><td><code>doctor</code>, <code>demo</code>, secret redaction, and a professional production UX completed.</td></tr><tr><td><strong>4F</strong></td><td>Production Benchmark</td><td>3/5 (Experimental)</td><td>3/5 (Production)</td><td>60% Recovery</td><td>Production bugs (e.g. duplicate action state handling) fixed; validated that architecture refactoring preserved capability.</td></tr><tr><td><strong>5A</strong></td><td>10-Case Benchmark Expansion</td><td>5 cases (3/5)</td><td>10 cases (7/10)</td><td>70% Recovery</td><td>5 new, distinct failure modes added (DEV-06–DEV-10). The generic architecture resolved 4/5 new cases autonomously.</td></tr></tbody></table><h2 id="failed-experiments-lessons-learned" tabindex="-1">Failed Experiments &amp; Lessons Learned <a class="header-anchor" href="#failed-experiments-lessons-learned" aria-label="Permalink to &quot;Failed Experiments &amp; Lessons Learned&quot;">​</a></h2><p>Our engineering progression involved numerous failed hypotheses. Documenting them is critical:</p><ul><li><strong>Stronger Prompts Do Not Solve Reasoning (Phase 3H)</strong>: Enforcing a strict, structured reasoning loop (OBSERVE → HYPOTHESIZE → INSPECT → ACT → VERIFY) on <code>gpt-4o-mini</code> did not improve the verified recovery rate. The model still failed at complex environmental inference.</li><li><strong>Quota Limits Break Agents (Phase 3F)</strong>: The Gemini Free Tier experiment proved that autonomous agents require significant API bandwidth. Rate limiting fundamentally broke the ReAct loop.</li><li><strong>Overzealous Duplicate Detection (Phase 3H)</strong>: Attempting to prevent infinite loops by hard-blocking repeated identical tool calls accidentally prevented the agent from re-inspecting files that had legitimately changed state between iterations.</li><li><strong>False Negative Verifiers (Phase 3I)</strong>: An overly aggressive verifier on DEV-03 returned failures for legitimate HTTP startups. The agent cannot succeed if the ground-truth verifier is flawed.</li><li><strong>Iteration Budgets (Phase 3I)</strong>: Attempting to cap iterations at 8 to save costs caused cascading failures (like DEV-05) to fail right as the agent was patching the final error.</li></ul><p><strong>Key Lesson</strong>: Do not trust the LLM to self-evaluate, but do trust it to iterate. Provide a long iteration runway (15+ iterations) governed by a flawless, deterministic verifier.</p><h2 id="measured-improvements" tabindex="-1">Measured Improvements <a class="header-anchor" href="#measured-improvements" aria-label="Permalink to &quot;Measured Improvements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Earlier</th><th>Later</th><th>Change</th></tr></thead><tbody><tr><td><strong>Verified Recovery Rate (5-case)</strong></td><td>1/5 (20%) - Phase 3G</td><td>3/5 (60%) - Phase 3J/4F</td><td>+40% (via calibration and budget)</td></tr><tr><td><strong>Verified Recovery Rate (10-case)</strong></td><td>3/5 (60%) - Phase 4F</td><td>7/10 (70%) - Phase 5A</td><td>Expanded baseline capability</td></tr><tr><td><strong>Maximum Iteration Budget</strong></td><td>8 (Phase 3I)</td><td>15 (Phase 3J)</td><td>+7 iterations (enabled cascading fixes)</td></tr><tr><td><strong>Safety Violations (Host Leakage)</strong></td><td>Unprotected <code>execSync</code></td><td>0 (Docker + execFile)</td><td>Complete isolation achieved</td></tr><tr><td><strong>Average Repair Latency</strong></td><td>Not measured</td><td>~5s to 90s (Phase 5A)</td><td>Varies heavily by case complexity</td></tr><tr><td><strong>Token Usage &amp; Cost</strong></td><td>Not measured</td><td>Not measured</td><td>Depended entirely on iteration depth</td></tr><tr><td><strong>Tool Reliability</strong></td><td>Occasional JSON errors</td><td>~100%</td><td>Handled via Controller malformed-recovery</td></tr></tbody></table><p><em>(Note: The preservation of the 3/5 recovery rate between the experimental Phase 3J and the production Phase 4F demonstrates that our production security refactoring successfully preserved agent capability without regressions).</em></p><h2 id="primary-metric" tabindex="-1">Primary Metric <a class="header-anchor" href="#primary-metric" aria-label="Permalink to &quot;Primary Metric&quot;">​</a></h2><p><strong>PRIMARY METRIC</strong>: Verified Recovery Rate <em>Definition</em>: The number of benchmark cases where the deterministic verifier independently confirmed the environment was successfully repaired divided by the total number of benchmark cases.</p><h2 id="secondary-metrics" tabindex="-1">Secondary Metrics <a class="header-anchor" href="#secondary-metrics" aria-label="Permalink to &quot;Secondary Metrics&quot;">​</a></h2><ol><li>Tool-call reliability (ability to gracefully recover from malformed JSON).</li><li>Average repair iterations (efficiency of the diagnostic path).</li><li>Repair latency.</li><li>Token usage/cost.</li><li>Safety violations (host isolation).</li></ol><h2 id="engineering-lessons" tabindex="-1">Engineering Lessons <a class="header-anchor" href="#engineering-lessons" aria-label="Permalink to &quot;Engineering Lessons&quot;">​</a></h2><p>Building a reliable troubleshooting agent requires accepting that <strong>LLMs will hallucinate success</strong>. The most critical component of the architecture is not the prompt or the LLM provider, but the <strong>Deterministic Boundary</strong>. When you strip the LLM of its ability to say &quot;I&#39;m done&quot; and instead force it to satisfy a programmatic health-check, the LLM stops guessing and starts engineering.</p><p>Furthermore, robust security (Docker isolation, <code>execFile</code> parameterization, credential scrubbing) is non-negotiable. Autonomous agents execute arbitrary commands generated by unpredictable models; they cannot be trusted with raw host access.</p><h2 id="current-state" tabindex="-1">Current State <a class="header-anchor" href="#current-state" aria-label="Permalink to &quot;Current State&quot;">​</a></h2><p>DevFix is a validated, production-ready autonomous troubleshooting CLI. It relies on a strictly decoupled architecture:</p><ol><li><strong>Intelligence</strong>: <code>deepseek-chat</code> Provider</li><li><strong>Execution</strong>: Secure Docker Sandbox &amp; Tool Registry</li><li><strong>Validation</strong>: Generic Deterministic Verifier</li></ol><p>It has been rigorously benchmarked against 10 distinct, reproducible local development failures, achieving a validated <strong>70% (7/10) Verified Recovery Rate</strong>. The codebase is fully unit-tested (36/36 passing) and cleanly isolated from host security vulnerabilities.</p><p>All evidence, runs, and artifacts supporting these conclusions are preserved in <code>artifacts/</code>, <code>docs/</code>, and <code>tests/</code>.</p>',25)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
